"""Author all 44 Cooking cards from preserved sources and the source conference."""
from pathlib import Path
from copy import deepcopy
from fractions import Fraction
import json,hashlib,re

ROOT=Path(__file__).resolve().parents[1];GAME=ROOT.parents[1];AUDIT=GAME/'docs/audit/2026-10-08/full-game'
GUIDE='docs/mechanics/COOKING_RECIPE_PLAYTEST.md'
FOOD_NAMES={'Meat','Milk','Fruit','Vegetables','Flour','Butter','Honey','Sugar','Eggs','Oil','Bear meat','Fire meat','Poisonous meat','Quetzalcoatlus meat','Sea meat','Vulture meat'}
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def dump(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def frac(x):return {'numerator':x.numerator,'denominator':x.denominator}
def ceil_hundredth(x):return Fraction((x.numerator*100+x.denominator-1)//x.denominator,100)

def main():
    if (ROOT/'docs/mechanics/COOKING_REVIEW_STATUS.json').exists():raise SystemExit('Reviewed Cooking exists; refusing draft overwrite.')
    e=read(AUDIT/'COOKING_SOURCE_EVIDENCE.json');recipes=e['recipes'];source=read(ROOT/'data/crafting/Decennium_Descent_Crafting_Bible_v4.json')
    assert recipes==[r for r in source['recipes'] if r['skill']=='Cooking']
    classified={r['recipeId']:r for r in read(AUDIT/'COOKING_EFFECT_CLASSIFICATION.json')['rows']}
    cards=[];nutrition=[]
    for r in recipes:
        rid=r['id'];q=r['quantity'];cl=classified[rid];kind=cl['sourceKind'];m=r['mechanics'];explicit_hours=cl.get('explicitRiderHours');parent_seconds=28800 if rid=='recipe-633' else None
        effect={'kind':kind,'recipeTags':[m['tag']] if 'tag' in m else [],'magical':True,'spell':False,'concentration':False,'temporaryHP':m['temporaryHP'],'parentDurationSeconds':parent_seconds,'parentEndsAtNextBeneficialLongRest':parent_seconds is None,'riderDurationSeconds':explicit_hours*3600 if explicit_hours is not None else None,'riderEndsWithParent':True,'shieldDepletionEndsRider':False,'acceptedFeastRequired':True}
        if kind=='damage-resistance':effect['damageType']=cl['damageType'];prose=f"Gain resistance to {cl['damageType']} damage for {explicit_hours} elapsed hour(s), ending earlier with the parent feast."
        elif kind=='poison-save-advantage':effect['advantageAgainst']=['poison'];prose=f'Gain advantage on saves against poison for {explicit_hours} elapsed hours, ending earlier with the parent feast. No poison immunity, condition cure or damage resistance.'
        elif kind=='poison-disease-save-advantage':effect['advantageAgainst']=['poison','disease'];prose='Gain advantage on saves against poison and disease until the parent feast ends. No automatic condition cure or immunity.'
        elif kind=='rp-recovery':effect.update(rpRestored=1,requiresExistingRpPool=True,cappedAtActualRpMaximum=True,oncePerRestLimit=None,clearsDissonance=False,clearsRefrain=False,convertsOtherResources=False);prose='On accepting this completed feast, restore 1 expended RP, capped at the actual existing RP maximum. There is no new once-per-rest cap: another genuine paid serving requires its full consumption and accepted feast replacement. No pool creation, RC conversion, Dissonance/Refrain reset, partial-meal or replay recovery.'
        elif kind=='athletics-bonus':effect.update(skill='Athletics',skillCheckBonus=cl['bonus']);prose=f"Gain +{cl['bonus']} to actual Athletics checks until the parent feast ends."
        elif kind=='stealth-bonus':effect.update(skill='Stealth',skillCheckBonus=cl['bonus']);prose=f"Gain +{cl['bonus']} to actual Stealth checks until the parent feast ends. No automatic Hidden state."
        elif kind=='constitution-save-bonus':effect.update(saveAbility='CON',saveBonus=cl['bonus']);prose=f"Gain +{cl['bonus']} to actual Constitution saving throws until the parent feast ends, including concentration and Wound/Injury saves when they are CON saves. Other roll types are not converted."
        elif kind=='movement-speed':effect.update(walkingSpeedBonusFeet=10,independentOtherModesIncreased=False);prose='Increase walking speed by 10 feet for 1 elapsed hour or until the parent feast ends, whichever comes first. Other movement modes change only if their own rule derives them from walking speed.'
        elif kind=='swim-speed':effect.update(swimSpeedEquals='current effective walking speed',dynamicallyRecalculated=True,createsWalkingMode=False,waterBreathing=False);prose='For 1 elapsed hour or until the parent feast ends, whichever comes first, gain a swimming speed equal to current effective walking speed, recalculated as that speed changes. No new walking mode, water breathing, underwater sight or current immunity.'
        elif kind=='prone-defense-advantage':effect['qualifyingRoll']='actual check or save whose direct consequence includes becoming Prone';prose='For 1 elapsed hour or until the parent feast ends, whichever comes first, gain advantage on an actual check or save whose direct consequence includes becoming Prone. No immunity to automatic Prone effects or benefit when standing.'
        elif kind=='first-charm-fear-save':effect.update(advantageAgainst=['Charmed','Frightened'],riderUses=1,riderConsumption='first actual qualifying saving throw resolution, even with other advantage');prose='Before the parent feast ends, gain advantage on the first actual save against charm or fear. That save spends this one rider even if another source already grants advantage. No save required means no use spent; no cure or immunity.'
        else:raise ValueError(kind)
        trait=None
        if m.get('wholeCreatureSynergy'):
            trait={'requiresVerifiedDonorProvenanceBeforeWork':True,'requiresPredeclaredApprovedTraitBeforeWork':True,'missingEligibleProfilePreventsWorkStart':True,'qualifyingProvenance':['same recorded creature','documented concrete shared ecology'],'trigger':'actual Masterwork margin at least 10; natural 1 never qualifies','additionalToGenericQualityChoice':True,'durationSeconds':3600,'endsWithParentFeast':True,'eligibleKinds':['printed walking/climbing/swimming speed','one printed damage resistance','bounded ordinary sensory capability'],'unreviewedOtherPassiveTraitsAllowed':False,'excluded':['attacks','extra actions','copied ability scores or HP','spellcasting','resources','healing or regeneration','temporary HP generation','damage or condition immunity','legendary/lair powers','identity/lifecycle effects','flight or burrowing','blindsight/truesight/tremorsense/telepathy']}
            prose+=' On an actual Masterwork craft, also grant the single approved donor trait fixed before work, for 1 hour or until this feast ends. Verified same-creature/shared-ecology provenance and an eligible donor profile are prerequisites to starting this recipe; see the shared procedure.'
        consumed=sum(Fraction(str(c['weight']))*c['quantity'] for c in r['components'] if c['consumed'])
        nutritive=sum(Fraction(str(c['weight']))*c['quantity'] for c in r['components'] if c['consumed'] and c['name'] in FOOD_NAMES)
        foodcat=max((Fraction(str(c['weight'])) for c in r['components'] if c['consumed'] and c['role']=='catalyst' and c['name'] in FOOD_NAMES),default=Fraction(0))
        max_yield=q*3//2;max_deficit=ceil_hundredth(max(Fraction(0),Fraction(2*max_yield,3)-(nutritive-foodcat)))
        std_deficit=ceil_hundredth(max(Fraction(0),Fraction(2*q,3)-nutritive))
        nutrows=[{'componentIndex':i,'componentId':c['id'],'name':c['name'],'countsAsNutritiveInput':c['name'] in FOOD_NAMES,'countedMassLb':float(Fraction(str(c['weight']))*c['quantity']) if c['consumed'] and c['name'] in FOOD_NAMES else 0,'basis':'ordinary edible food after actual recipe preparation; Oil means food-grade cooking oil' if c['name'] in FOOD_NAMES else 'not credited as nutritive bulk by this card; no verified edible-food profile supplied'} for i,c in enumerate(r['components'])]
        nutrition.append({'recipeId':rid,'sourceConsumedMassLb':float(consumed),'nutritiveInputMassLb':float(nutritive),'worstRetainedNutritiveCatalystLb':float(foodcat),'standardAdditionalFoodLb':float(std_deficit),'masterworkMaximumAdditionalFoodLb':float(max_deficit),'components':nutrows})
        work=r['workRequirements']['activeWorkHours'];overlay=1920 if work is None and rid=='recipe-120' else work;assert overlay is not None
        flaw={'mode':'contaminated-serving','quantity':1,'materialRecoveryPercent':0} if rid=='recipe-633' else {'mode':'half-batch-quantity','quantity':q//2} if q>=2 else {'mode':'treat-as-Failed','quantity':0,'materialRecoveryPercent':25}
        failure=None
        if rid=='recipe-633':failure={'trigger':'any total below DC or Mishap/natural 1','servings':1,'createsFeastRecord':False,'temporaryHP':0,'beneficialRider':None,'materialRecoveryPercent':0,'mishapAlsoResolves':True,'exposureAfterFullConsumptionSeconds':600,'saveAbility':'CON','saveDC':13,'onFailureCondition':'Poisoned','conditionDurationSeconds':3600,'damage':None,'nutritionCreditIfFullyConsumed':True,'shelfLifeSeconds':86400,'partialConsumptionCreatesExposure':False,'coatingOrExtractablePoison':False,'automaticResaleValue':None}
        op={'text':f"After completing and accepting this feast, offer {m['temporaryHP']} temporary HP. "+prose,'effect':effect,'traitRider':trait,'failureOverride':failure,
            'activation':{'activeMinutes':10,'regularTurnActions':100,'minimumElapsedSeconds':600,'additionalActionAfterRequiredCount':False,'oneEaterOrFeederThroughout':True,'recipientLocked':True,'consent':'willing or Incapacitated with actual helper and compatible swallowing route','servingSpentAtLegalStart':True,'noBenefitBeforeCompletion':True,'interruptionLeavesOldFeast':True,'declineMagicStillCountsCompletedFood':True},
            'physical':{'foodWeightLb':frac(Fraction(2,3)),'defaultPackagingItemId':'cooking-containers.lidded-meal-crock','defaultPackagingWeightLb':.5,'defaultGrossWeightLb':frac(Fraction(7,6)),'servings':1,'shelfLifeSeconds':86400,'spoilsWithoutDegradedStage':True,'consumptionNeedOnlyStartBeforeShelfDeadline':True},
            'nutrition':{'dailySmallMediumFoodFraction':frac(Fraction(1,3)),'dailyLargeFoodFraction':frac(Fraction(1,6)),'waterFuelOrSupplyCredit':0,'nutritiveInputMassLb':float(nutritive),'worstRetainedNutritiveCatalystLb':float(foodcat),'supplementaryRationReferenceCpPerLb':25,'standardSupplementaryFoodLb':float(std_deficit),'maximumMasterworkSupplementaryFoodLb':float(max_deficit),'reserveRoundedUpToLb':.01,'sourceComponents':nutrows},
            'craft':{'sourceActiveWorkHours':work,'operationalActiveWorkHours':overlay,'workTimeProvenance':'reviewed one-workyear overlay' if work is None else 'source','firstBindingPhaseMinutes':15,'phaseIncludedInWork':True,'maximumYield':max_yield,'maximumYieldNutritionAndCapacityReservedBeforeCheck':True,'standardQuantity':q,'flawed':flaw,'durabilityOnlyDedicatedMundanePackaging':True,'standardQuantityOnlyWhenDurabilityChosen':True,'mealCrockQualityMaxHP':3,'potencyImproved':False},
            'value':{'standardBatchReferenceGp':r['economy']['recommendedMarketValue'],'unitReferenceGp':frac(Fraction(r['economy']['recommendedMarketValue'],q)),'extraFoodAndPackagingOutsideSourceEconomics':True},'sharedRules':GUIDE}
        cards.append({'recipeId':rid,'name':r['name'],'visibility':r['visibility'],'status':'draft-awaiting-GPT-exact-review','sourceSha256':e['sourceSha256'],'sourceRecipeIndex':e['sourceIndices'][rid],'sourceEffect':r['effects'],'sourceMechanics':deepcopy(m),'sourceRecipeTags':deepcopy(r['tags']),'sourceLegacyFields':{k:deepcopy(r[k]) for k in ['legacyName','legacyEffect'] if k in r},'sourceRequirements':{k:deepcopy(r[k]) for k in ['skill','skillLevel','difficulty','tier','rarity','quantity','craftingTime','workRequirements','craftingCheck','discovery','components','economy','skillProgression']},'operational':op})
    envelope={'schemaVersion':1,'status':'draft-awaiting-GPT-exact-review','sourceConferenceTurnId':'d4ee39f9-b5b9-41b7-87bd-4fc4d09e843f','sourceSha256':e['sourceSha256'],'sharedRules':GUIDE,'runtimeImplemented':False,'balanceApproved':False,'newContainer':{'id':'cooking-containers.lidded-meal-crock','name':'Lidded Meal Crock','referencePriceCp':20,'emptyWeightLb':.5,'capacityQuarts':1,'maximumServings':1,'material':'glazed ceramic','AC':13,'HP':2,'reusable':True,'preservationBonus':False}}
    dump(ROOT/'data/playtest/cooking_recipe_candidate.json',{**envelope,'visibility':'public','cards':[c for c in cards if c['visibility']=='public']})
    dump(ROOT/'data/director/cooking_recipe_candidate_internal.json',{**envelope,'visibility':'director-internal','cards':cards})
    dump(AUDIT/'COOKING_NUTRITION_ACCOUNTING.json',{'status':'draft-for-exact-review','ordinaryEdibleNames':sorted(FOOD_NAMES),'policy':'Only the listed ordinary-food inputs count; all others remain real ingredients but receive zero nutritional credit until a separate approved edible profile exists. Deficit reservation is conservative and never replaces required ingredients.','recipes':nutrition})
    for public,path in [(True,ROOT/'docs/mechanics/COOKING_PUBLIC_RECIPE_CARDS.md'),(False,ROOT/'docs/director-only/COOKING_INTERNAL_RECIPE_CARDS.md')]:
        chosen=[c for c in cards if c['visibility']=='public'] if public else cards
        out=['# Cooking '+('public' if public else 'Director internal')+' recipe cards','','**Draft awaiting exact GPT review.** '+('30 public formulas.' if public else 'All 44 formulas: 30 public, two restricted, 12 Director-only. Keep this file internal.'),'','Every card uses the shared Cooking procedure for consumption, feast replacement, nutrition, storage, quality and donor-trait eligibility. Source quantities are servings; prices are Standard batch references. Source names and legacy fields remain preserved and do not grant additional powers.','']
        for c in chosen:
            s=c['sourceRequirements'];o=c['operational'];n=o['nutrition'];w=o['craft']
            out+=['## '+c['recipeId']+' — '+c['name'],'',f"**Source:** {c['visibility']}; Cooking level {s['skillLevel']}; tier {s['tier']}; {s['rarity']}; DC {s['difficulty']}; {w['operationalActiveWorkHours']} active hours; {s['quantity']} serving(s). Standard batch reference {s['economy']['recommendedMarketValue']} gp.",'','**Preserved effect:** '+c['sourceEffect'],'','**Operational effect:** '+o['text'],'','**Duration:** '+('Entire successful feast and its temporary HP last eight elapsed hours, including through a Long Rest.' if o['effect']['parentDurationSeconds'] else 'Parent feast and its temporary HP end at the next completed beneficial Long Rest.')+' Every rider also ends when this feast ends or is replaced. Its explicitly shorter deadline remains separate.','',
                '**Work:** '+s['workRequirements']['station']+'; '+', '.join(s['workRequirements']['requiredTools'])+f". Mode {s['workRequirements']['timeMode']}; field flag {str(s['workRequirements']['fieldCraftable']).lower()}; maximum assistants {s['workRequirements']['maximumAssistants']}; formula required {str(s['discovery']['requiresFormula']).lower()}.",'',
                '**Exact ingredients:** '+'; '.join(f"{x['quantity']} × {x['name']} (component tier {x['tier']}; {x['weight']} lb/unit; {x['value']} gp/unit; {x['role']}; {'consumed' if x['consumed'] else 'returned'})" for x in s['components'])+'.','',
                f"**Food reservation:** {n['nutritiveInputMassLb']:g} lb credited nutritive source inputs; up to {n['worstRetainedNutritiveCatalystLb']:g} lb may return as the selected catalyst. For Standard quantity without catalyst retention, add {n['standardSupplementaryFoodLb']:g} lb real ration-equivalent food. Before any completion check reserve {n['maximumMasterworkSupplementaryFoodLb']:g} lb supplementary food for full Masterwork yield and worst legal nutritive catalyst retention. This is additional to every exact ingredient. Actual food reference is 25 cp/lb, prorated from 5 sp per 2-lb daily ration; supplier quotes and transaction rounding still apply.",'',
                f"**Serving and storage:** each serving contains exactly 2/3 lb food and credits 1/3 Small/Medium daily food or 1/6 Large daily food after complete consumption. Reserve actual food-safe storage/serving capacity for {w['maximumYield']} possible servings before rolling; existing containers are used only to their real capacity. A dedicated Meal Crock is 0.5 lb empty, 2 sp, 1 quart, AC 13/HP 2; one serving gives 7/6 lb gross. No water, fuel or full Supply is supplied by this food credit. Finished-food shelf life is 24 unprotected elapsed hours.",'',
                '**Flawed:** '+json.dumps(w['flawed'],ensure_ascii=False)+'. Quality can change finite yield or dedicated mundane packaging durability; it does not improve meal potency.','',
                '**Nutritional source map:** '+'; '.join(x['name']+(' counts as ordinary food' if x['countsAsNutritiveInput'] else ' has no credited nutritive bulk in this card') for x in n['sourceComponents'])+'.','']
            if o['traitRider']:out+=['**Required donor record:** record actual donors for every monster-part lot, the same-creature/shared-ecology evidence, the one donor supplying a consumed component, and its approved eligible trait before starting work. No eligible profile means this work order cannot begin. On actual Masterwork, the fixed trait accompanies the normal quality choice for one hour or until the feast ends. No post-roll choice or fallback power.','']
            if o['failureOverride']:out+=['**Contaminated failure:** any total below DC, or Mishap/natural 1, creates one contaminated serving with no feast magic and no material recovery. Mishap also applies normally. Full ten-minute consumption gives ordinary food credit and a DC 13 CON save; failure causes Poisoned for one elapsed hour, success no condition. It does not replace an existing feast. No damage, partial-dose poison, coating or guaranteed sale value.','']
            if s['workRequirements']['activeWorkHours'] is None:out+=['**Work-year binding:** source active hours remain null; this card uses the reviewed 1,920-active-hour work-year overlay. Actual eligible artisan time reduction applies to that work without changing the source.','']
        path.parent.mkdir(parents=True,exist_ok=True);path.write_text('\n'.join(out),encoding='utf-8')
    print(json.dumps({'cards':len(cards),'public':sum(c['visibility']=='public' for c in cards),'sourceNutritionNames':len(FOOD_NAMES),'nonzeroSupplementalFoodRecipes':sum(c['operational']['nutrition']['maximumMasterworkSupplementaryFoodLb']>0 for c in cards)}))

if __name__=='__main__':main()
